import sys
from pathlib import Path

import numpy as np
import pandas as pd

BOROUGHS = ["MANHATTAN", "BRONX", "BROOKLYN", "QUEENS", "STATEN ISLAND"]
WALLS = ["Brick Masonry", "Terra Cotta", "Concrete", "Curtain Wall", "Stone"]
CYCLE_YEAR = {"7": 2012, "8": 2017, "9": 2022}


def main(folder, n_buildings=900, seed=1):
    rng = np.random.default_rng(seed)
    raw = Path(folder) / "raw"
    raw.mkdir(parents=True, exist_ok=True)

    boro = rng.integers(1, 6, n_buildings)
    block = rng.integers(1, 9000, n_buildings)
    lot = rng.integers(1, 200, n_buildings)
    bins = [f"{b}{rng.integers(0, 999999):06d}" for b in boro]
    year_built = rng.integers(1890, 2015, n_buildings)
    risk = (2000 - year_built) / 60 + rng.normal(0, 1, n_buildings)

    filings, violations = [], []
    for i in range(n_buildings):
        walls = list(rng.choice(WALLS, size=rng.integers(1, 3), replace=False))
        n_viol = rng.poisson(max(0.2, 1 + risk[i]))
        for _ in range(n_viol):
            day = pd.Timestamp("2000-01-01") + pd.Timedelta(days=int(rng.integers(0, 9000)))
            violations.append({
                "bin": bins[i], "issue_date": day.strftime("%Y%m%d"),
                "severity": rng.choice(["CLASS - 1", "CLASS - 2", "CLASS - 3"], p=[.3, .5, .2]),
                "violation_type": rng.choice(["Construction", "Elevators", "Boilers"], p=[.6, .2, .2]),
                "ecb_violation_status": rng.choice(["ACTIVE", "RESOLVE"]),
            })
        for cycle, year in CYCLE_YEAR.items():
            if year < year_built[i] + 5 or rng.random() < 0.1:
                continue
            p_unsafe = 1 / (1 + np.exp(-(risk[i] + 0.25 * n_viol - 2.2 + ("Terra Cotta" in walls))))
            status = "UNSAFE" if rng.random() < p_unsafe else rng.choice(["SAFE", "SWARMP"])
            date = pd.Timestamp(f"{year}-01-01") + pd.Timedelta(days=int(rng.integers(0, 700)))
            row = {"tr6_no": f"TR6-{len(filings):06d}", "control_no": str(100000 + len(filings)),
                   "filing_type": "Initial", "cycle": cycle, "bin": bins[i],
                   "borough": BOROUGHS[boro[i] - 1], "block": str(block[i]), "lot": str(lot[i]),
                   "filing_date": date.strftime("%m/%d/%Y"), "filing_status": status,
                   "current_status": status, "exterior_wall_type": "; ".join(walls),
                   "exterior_wall_material": rng.choice(["Masonry", "Glass", "Metal", "Masonry, Stone"])}
            filings.append(row)
            if rng.random() < 0.25:   # an amended filing that must be ignored
                filings.append({**row, "filing_type": "Amended", "filing_status": "SAFE"})

    pluto = pd.DataFrame({
        "bbl": [f"{b}{bl:05d}{lt:04d}.00000000" for b, bl, lt in zip(boro, block, lot)],
        "borough": [["MN", "BX", "BK", "QN", "SI"][b - 1] for b in boro],
        "block": block, "lot": lot,
        "bldgclass": rng.choice(["D4", "D1", "O4", "C6", "R4"], n_buildings),
        "numfloors": rng.integers(7, 40, n_buildings),
        "yearbuilt": year_built,
        "yearalter1": np.where(rng.random(n_buildings) < 0.4, rng.integers(1980, 2024, n_buildings), 0),
        "yearalter2": 0,
        "bldgarea": rng.integers(20000, 900000, n_buildings),
        "unitstotal": rng.integers(0, 400, n_buildings),
        "landmark": np.where(rng.random(n_buildings) < 0.05, "INDIVIDUAL LANDMARK", ""),
        "histdist": np.where(rng.random(n_buildings) < 0.15, "Some Historic District", ""),
        "latitude": 40.6 + rng.random(n_buildings) * 0.25,
        "longitude": -74.05 + rng.random(n_buildings) * 0.25,
    }).sample(frac=0.94, random_state=seed)   # 6% of buildings have no PLUTO match

    pd.DataFrame(filings).to_csv(raw / "facades.csv", index=False)
    pluto.to_csv(raw / "pluto.csv", index=False)
    pd.DataFrame(violations).to_csv(raw / "ecb.csv", index=False)
    print(f"Wrote FAKE data to {raw}: {len(filings):,} filings, "
          f"{len(pluto):,} lots, {len(violations):,} violations")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "data_fake")
